const $=id=>document.getElementById(id);
const scenarios=[{id:'friend',emoji:'👋',name:'A friend',sub:'“5 minutes away”',messages:['Your friend said they’re on their way.','They have entered the “putting on shoes” phase.','Their five minutes exist in a different time zone.','Location update: still suspiciously stationary.','Your friend has become a philosophical concept.']},{id:'food',emoji:'🍕',name:'Food delivery',sub:'Hangry is a feeling',messages:['The restaurant has acknowledged your hunger.','Your order is enjoying a brief sightseeing tour.','The driver is nearby. Cosmically speaking.','Your fries are contemplating their purpose.','Estimated arrival: before your next meal. Maybe.']},{id:'wifi',emoji:'📶',name:'Wi-Fi',sub:'Connected. Or not.',messages:['Searching for a meaningful connection.','Connected. Emotionally.','Turning it off and on has entered the chat.','One bar. Infinite possibilities. None loading.','Your router requests some personal space.']},{id:'reply',emoji:'💬',name:'A reply',sub:'Seen at 2:34 PM',messages:['Message delivered. Expectations elevated.','They’re typing… or polishing their keyboard.','Typing stopped. Character development cancelled.','No new information. Plenty of new theories.','Your message is aging like a fine wine.']},{id:'motivation',emoji:'⚡',name:'Motivation',sub:'Any day now…',messages:['Preparing to prepare to get started.','Motivation scheduled for tomorrow. Again.','A small spark! Never mind, just a notification.','Your potential remains impressively untapped.','Doing nothing is technically doing something.']}];
const badges=[{id:'first',icon:'🌱',name:'A promising lack of effort',desc:'Start your first waiting session.'},{id:'minute',icon:'⏳',name:'Still here?',desc:'Wait for one full minute.'},{id:'refresh',icon:'👀',name:'Refresh reflex',desc:'Check again ten times in one session.'},{id:'friend',icon:'🕰️',name:'Five more minutes',desc:'Wait for a friend for five minutes.'},{id:'ten',icon:'🧘',name:'Character development',desc:'Wait for ten minutes in one session.'},{id:'motivation',icon:'🛋️',name:'Tomorrow, definitely',desc:'Give up waiting for motivation.'}];
let db={sessions:[],unlocked:[],active:null},selected='friend',toastTimeout;
try{const saved=JSON.parse(localStorage.getItem('wait-simulator-v1'));if(saved&&Array.isArray(saved.sessions)&&Array.isArray(saved.unlocked)){db=saved;if(db.active&&(!scenarios.some(s=>s.id===db.active.scenario)||!Number.isFinite(db.active.start)))db.active=null;}}catch{}
if(db.active)selected=db.active.scenario;
function save(){try{localStorage.setItem('wait-simulator-v1',JSON.stringify(db));}catch{toast('Browser storage is unavailable. This wait lives in this tab.');}}
function current(){return scenarios.find(s=>s.id===selected)}
function elapsed(){return db.active?Math.max(0,Math.floor((Date.now()-db.active.start)/1000)):0}
function format(s){return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<35;i++){const p=document.createElement('i');p.className='confetti';p.style.left=Math.random()*100+'vw';p.style.background=['#7653e7','#c7ef8a','#ffb96b','#d9cafa'][i%4];p.style.animationDelay=Math.random()*.5+'s';document.body.append(p);setTimeout(()=>p.remove(),2700)}}
function unlock(id){if(db.unlocked.includes(id))return;db.unlocked.push(id);save();const badge=badges.find(b=>b.id===id);toast(`✧ Achievement unlocked: ${badge.name}`);celebrate();renderAchievements()}
function renderScenarios(){$('scenarios').innerHTML=scenarios.map(s=>`<button class="scenario ${selected===s.id?'selected':''}" aria-pressed="${selected===s.id}" data-scenario="${s.id}"><span class="radio"></span><span class="emoji">${s.emoji}</span><strong>${s.name}</strong><small>${s.sub}</small></button>`).join('');document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>select(b.dataset.scenario));$('scene').textContent=current().emoji;}
function select(id){if(db.active){toast('Finish this wait first. One existential crisis at a time.');return false}selected=id;renderScenarios();renderFeed();return true}
function renderFeed(){const entries=db.active?.feed||[{text:'Your waiting room is ready.',time:0},{text:'Pick your reason. Lower your expectations.',time:0}];$('feed').innerHTML=entries.slice(-4).reverse().map((m,i)=>`<div class="feed-item"><span class="feed-icon">${i===0?'✦':'·'}</span><div><p></p><small>${format(m.time)} · ${i===0?'Latest update':'Previously, nothing'}</small></div></div>`).join('');$('feed').querySelectorAll('p').forEach((p,i)=>p.textContent=entries.slice(-4).reverse()[i].text)}
function message(text){if(db.active){db.active.feed.push({text,time:elapsed()});db.active.feed=db.active.feed.slice(-10);save();renderFeed()}else toast(text)}
function start(){if(db.active)return;db.active={scenario:selected,start:Date.now(),checks:0,sighs:0,event:0,feed:[{text:current().messages[0],time:0}]};save();unlock('first');renderSession();renderFeed();tick()}
function renderSession(){const active=!!db.active;document.body.classList.toggle('running',active);$('state-label').textContent=active?'◷ Professionally waiting':'○ Ready to do nothing';$('session-label').textContent=active?`WAITING FOR ${current().name.toUpperCase()}`:'YOUR PERSONAL WAITING SPACE';$('session-actions').innerHTML=active?'<button class="primary" id="finish">It finally happened! ✧</button><button class="secondary" id="give-up">I give up</button>':'<button class="primary" id="start">Let’s wait <span>↗</span></button>';if(active){$('finish').onclick=()=>finish(true);$('give-up').onclick=()=>finish(false)}else $('start').onclick=start;}
function finish(completed){if(!db.active)return;const duration=elapsed(),record={...db.active,duration,completed,end:Date.now()};if(!completed&&selected==='motivation')unlock('motivation');db.sessions.unshift(record);db.sessions=db.sessions.slice(0,200);db.active=null;save();$('summary-title').textContent=completed?'The wait is over. Somehow.':'You chose inner peace.';$('summary-copy').textContent=`You waited for ${current().name.toLowerCase()} and checked ${record.checks} ${record.checks===1?'time':'times'}.`;$('summary-time').textContent=format(duration);$('summary').showModal();if(completed)celebrate();renderSession();renderFeed();renderStats();tick()}
function tick(){const s=elapsed(),a=db.active;$('timer').textContent=format(s);const progress=a?Math.min(99,Math.round(100*(1-Math.exp(-s/(selected==='motivation'?500:90))))):0;$('progress-fill').style.width=progress+'%';$('progress-text').textContent=progress+'%';$('timer-caption').textContent=a?(s<60?'Look at you. Absolutely nailing doing nothing.':s<300?'Still waiting. A masterclass in commitment.':'Time is a construct. This wait is very real.'):'A little patience. A lot of possibilities.';$('progress-note').textContent=progress>90?'The last few percent require emotional support.':'Absolutely no scientific basis whatsoever.';const score=a?Math.max(0,Math.min(100,100-a.checks*4+Math.floor(s/15))):100;$('score').textContent=score;$('patience-name').textContent=score>75?'Unbothered.':score>40?'Slightly bothered.':'Deep breaths.';$('patience-copy').textContent=score>75?'Let’s see how long that lasts.':score>40?'The refresh button has noticed.':'The universe is taking its time.';if(a){const event=Math.floor(s/15);if(event>a.event){a.event=event;message(event<current().messages.length?current().messages[event]:['No new information available. Consistency is key.','We checked the situation. It remains a situation.','Your patience has been forwarded to the relevant department.','This is the longest “just a moment” in recorded history.'][event%4])}if(s>=60)unlock('minute');if(s>=300&&selected==='friend')unlock('friend');if(s>=600)unlock('ten')}}
function renderStats(){const sessions=db.sessions,total=sessions.reduce((n,s)=>n+s.duration,0);$('stats-grid').innerHTML=[['Total time well wasted',format(total)],['Waiting sessions',sessions.length],['Longest wait',format(Math.max(0,...sessions.map(s=>s.duration)))],['Things that finally happened',sessions.filter(s=>s.completed).length],['Status checks',sessions.reduce((n,s)=>n+s.checks,0)],['Achievements unlocked',`${db.unlocked.length} / ${badges.length}`]].map(([label,value])=>`<article class="stat"><span>${label}</span><strong>${value}</strong></article>`).join('');$('history').innerHTML=sessions.length?sessions.slice(0,10).map(s=>`<div class="history-row"><span>${scenarios.find(x=>x.id===s.scenario)?.emoji||'◷'} ${scenarios.find(x=>x.id===s.scenario)?.name||'A wait'}</span><small>${s.completed?'Finally happened':'Chose inner peace'}</small><strong>${format(s.duration)}</strong></div>`).join(''):'<p class="view-sub">A beautifully empty record. Finish your first wait to make history.</p>'}
function renderAchievements(){$('achievement-grid').innerHTML=badges.map(b=>`<article class="achievement ${db.unlocked.includes(b.id)?'':'locked'}"><span>${b.icon}</span><h3>${b.name}</h3><p>${b.desc}</p><small>${db.unlocked.includes(b.id)?'✧ Unlocked':'○ Keep waiting'}</small></article>`).join('')}
function view(name){['wait','stats','achievements'].forEach(v=>$(v+'-view').hidden=v!==name);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));renderStats();renderAchievements()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('see-achievements').onclick=()=>view('achievements');$('check').onclick=()=>{if(!db.active)return toast('Start a wait. Then we can check on absolutely nothing.');db.active.checks++;message('Extensive investigation complete. Still waiting.');if(db.active.checks>=10)unlock('refresh');tick()};$('sigh').onclick=()=>{if(db.active){db.active.sighs++;save()}toast('☁ A deeply theatrical sigh. The universe remains unmoved.');$('scene').classList.add('popped');setTimeout(()=>$('scene').classList.remove('popped'),550)};$('scene').onclick=()=>{message(selected==='friend'?'Nudge sent to the imaginary friend. They said “almost there.”':'You poked it. It is now aware of your disappointment.');$('scene').classList.add('popped');setTimeout(()=>$('scene').classList.remove('popped'),550)};$('progress').onclick=()=>toast('Pressure does not help. But we admire the effort.');$('close-summary').onclick=()=>$('summary').close();$('again').onclick=()=>{$('summary').close();view('wait')};renderScenarios();renderSession();renderFeed();renderStats();renderAchievements();tick();setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_wait',description:'Start a waiting session for a chosen scenario. Fails if a wait is active.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:scenarios.map(s=>s.id)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!scenarios.some(s=>s.id===input.scenario))throw new Error('Unknown scenario');if(db.active)throw new Error('A wait is already active');select(input.scenario);view('wait');start();return {scenario:selected,started:true}}})).catch(()=>{})}catch{}}
